const question = (text, options, correctAnswer, explanation) => ({ text, options, correctAnswer, explanation })
const topic = (name, slug, easy, medium, hard, children = []) => ({
  name,
  slug,
  icon: 'book',
  questions: [
    { difficulty: 'Easy', ...easy },
    { difficulty: 'Medium', ...medium },
    { difficulty: 'Hard', ...hard },
  ],
  children,
})
const legacy = (name, slug, icon, easy, medium, hard) => ({
  ...topic(name, slug, easy, medium, hard),
  icon,
  legacy: true,
})

