export const legacyCategoryParents = {
  javascript: 'programming',
  python: 'programming',
  react: 'web-development',
  html: 'web-development',
  css: 'web-development',
  'data-science': 'ai-machine-learning',
}

export function flattenSubjectCategories(groups = subjectGroups) {
  const rows = []
  const visit = (nodes, parentSlug = null, rootSlug = null) => {
    for (const node of nodes) {
      const { children = [], questions, legacy: isLegacy, ...category } = node
      rows.push({ ...category, parentSlug, rootSlug: rootSlug || node.slug, legacy: Boolean(isLegacy) })
      visit(children, node.slug, rootSlug || node.slug)
    }
  }
  visit(groups)
  return rows
}

export function flattenSubjectQuizzes(groups = subjectGroups) {
  const quizzes = []
  const visit = nodes => {
    for (const node of nodes) {
      if (node.questions?.length) {
        for (const item of node.questions) {
          quizzes.push({
            title: `${node.name}: ${item.difficulty} practice`,
            description: `A focused ${item.difficulty.toLowerCase()} ${node.name.toLowerCase()} quiz.`,
            category: node.slug,
            difficulty: item.difficulty,
            timeLimit: 3,
            featured: false,
            questions: [item],
          })
        }
      }
      visit(node.children || [])
    }
  }
  visit(groups)
  return quizzes
}
